package com.bookreads.ui.home

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.bookreads.api.UserRepository
import com.bookreads.storage.LocalSessionStore
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class HomeViewModel(
    private val userRepository: UserRepository,
    private val localSessionStore: LocalSessionStore,
) : ViewModel() {

    private val _viewState = MutableStateFlow<HomeViewState>(HomeViewState.Idle)
    val viewState: StateFlow<HomeViewState> = _viewState.asStateFlow()

    var onNavigateToSession: ((String) -> Unit)? = null

    fun handleEvent(event: HomeViewEvent) {
        when (event) {
            is HomeViewEvent.EnterUsername -> enterUsername(event.username)
        }
    }

    private fun enterUsername(username: String) {
        viewModelScope.launch {
            _viewState.value = HomeViewState.Loading
            runCatching {
                userRepository.getOrCreateUser(username)
                localSessionStore.saveUsername(username)
            }.onSuccess {
                onNavigateToSession?.invoke(username)
                _viewState.value = HomeViewState.Idle
            }.onFailure { e ->
                _viewState.value = HomeViewState.Error(e.message ?: "Unknown error")
            }
        }
    }
}
