package com.bookreads.ui.session

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.bookreads.api.SessionSyncService
import com.bookreads.dto.SessionSyncRequest
import com.bookreads.storage.LocalSessionStore
import com.bookreads.storage.SessionData
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.datetime.Clock

class SessionViewModel(
    private val sessionSyncService: SessionSyncService,
    private val localSessionStore: LocalSessionStore,
) : ViewModel() {

    private val _viewState = MutableStateFlow<SessionViewState>(SessionViewState.Idle)
    val viewState: StateFlow<SessionViewState> = _viewState.asStateFlow()

    private var username: String = ""
    private var timerJob: Job? = null
    private var syncJob: Job? = null
    private var currentClientId: String? = null
    private var currentBookTitle: String? = null
    private var sessionStartEpochMs: Long = 0L
    private var elapsedOffsetSec: Long = 0L

    fun init(username: String) {
        this.username = username
        viewModelScope.launch {
            val saved = localSessionStore.getActiveSession()
            if (saved != null) {
                currentClientId = saved.clientId
                currentBookTitle = saved.bookTitle
                sessionStartEpochMs = saved.startedAtEpochMs
                elapsedOffsetSec = saved.elapsedOffsetSec
                startTimer(saved.bookTitle)
            }
        }
    }

    fun handleEvent(event: SessionViewEvent) {
        when (event) {
            is SessionViewEvent.StartReading -> startReading(event.bookTitle)
            SessionViewEvent.StopReading -> stopReading()
        }
    }

    private fun startReading(bookTitle: String) {
        val clientId = generateClientId()
        currentClientId = clientId
        currentBookTitle = bookTitle
        sessionStartEpochMs = Clock.System.now().toEpochMilliseconds()
        elapsedOffsetSec = 0L

        viewModelScope.launch {
            localSessionStore.saveActiveSession(
                SessionData(
                    clientId = clientId,
                    bookTitle = bookTitle,
                    startedAtEpochMs = sessionStartEpochMs,
                    elapsedOffsetSec = 0L,
                ),
            )
            fireSync(clientId, bookTitle, endedAt = null)
        }
        startTimer(bookTitle)
    }

    private fun startTimer(bookTitle: String) {
        timerJob?.cancel()
        timerJob = viewModelScope.launch {
            while (true) {
                val elapsed = elapsedOffsetSec + (Clock.System.now().toEpochMilliseconds() - sessionStartEpochMs) / 1000
                _viewState.value = SessionViewState.Active(bookTitle = bookTitle, elapsedSec = elapsed)
                delay(1_000L)
            }
        }
        syncJob?.cancel()
        syncJob = viewModelScope.launch {
            sessionSyncService.startPeriodicSync {
                val cid = currentClientId ?: return@startPeriodicSync null
                val title = currentBookTitle ?: return@startPeriodicSync null
                val elapsed = elapsedOffsetSec + (Clock.System.now().toEpochMilliseconds() - sessionStartEpochMs) / 1000
                buildSyncRequest(cid, title, elapsed, endedAt = null)
            }
        }
    }

    private fun stopReading() {
        timerJob?.cancel()
        syncJob?.cancel()
        val cid = currentClientId ?: return
        val title = currentBookTitle ?: return
        val elapsed = elapsedOffsetSec + (Clock.System.now().toEpochMilliseconds() - sessionStartEpochMs) / 1000
        val endedAt = Clock.System.now().toString()
        viewModelScope.launch {
            localSessionStore.clearActiveSession()
            fireSync(cid, title, endedAt = endedAt, durationSec = elapsed)
        }
        currentClientId = null
        currentBookTitle = null
        _viewState.value = SessionViewState.Idle
    }

    private suspend fun fireSync(clientId: String, bookTitle: String, endedAt: String?, durationSec: Long = 0L) {
        val request = buildSyncRequest(clientId, bookTitle, durationSec, endedAt)
        sessionSyncService.sync(request)
    }

    private fun buildSyncRequest(clientId: String, bookTitle: String, durationSec: Long, endedAt: String?) =
        SessionSyncRequest(
            clientId = clientId,
            username = username,
            bookTitle = bookTitle,
            startedAt = kotlinx.datetime.Instant.fromEpochMilliseconds(sessionStartEpochMs).toString(),
            endedAt = endedAt,
            durationSec = durationSec,
        )

    private fun generateClientId(): String = kotlinx.uuid.UUID.random().toString()
}
```

