        SessionSyncRequest(
            clientId = clientId,
            username = username,
            bookTitle = bookTitle,
            startedAt = epochMsToIso(sessionStartMs),
            endedAt = endedAt,
            durationSec = durationSec,
        )

    private fun elapsedSec(): Long = (currentTimeMs() - sessionStartMs) / 1000

    private fun currentTimeMs(): Long = System.currentTimeMillis()

    private fun epochMsToIso(ms: Long): String {
        val sec = ms / 1000
        val remainder = ms % 1000
        return "${sec}.${remainder.toString().padStart(3, '0')}Z"
    }

    private fun generateClientId(): String {
        val hex = "0123456789abcdef"
        fun rand(n: Int) = (0 until n).map { hex[(Math.random() * 16).toInt()] }.joinToString("")
        return "${rand(8)}-${rand(4)}-4${rand(3)}-${rand(4)}-${rand(12)}"
    }
