import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class LeaderboardViewModel(
    private val leaderboardRepository: LeaderboardRepository,
) : ViewModel() {

    private val _viewState = MutableStateFlow<LeaderboardViewState>(LeaderboardViewState.Loading)
    val viewState: StateFlow<LeaderboardViewState> = _viewState.asStateFlow()

    private val _selectedWindow = MutableStateFlow("alltime")
    val selectedWindow: StateFlow<String> = _selectedWindow.asStateFlow()

    private var pollJob: Job? = null

    init {
        startPolling()
    }

    fun handleEvent(event: LeaderboardViewEvent) {
        when (event) {
            is LeaderboardViewEvent.SelectWindow -> {
                _selectedWindow.value = event.window
                startPolling()
            }
            LeaderboardViewEvent.Refresh -> loadLeaderboard()
        }
    }

    private fun startPolling() {
        pollJob?.cancel()
        pollJob = viewModelScope.launch {
            while (true) {
                loadLeaderboard()
                delay(30_000L)
            }
        }
    }

    private fun loadLeaderboard() {
        viewModelScope.launch {
            runCatching {
                leaderboardRepository.getLeaderboard(_selectedWindow.value)
            }.onSuccess { entries ->
                _viewState.value = LeaderboardViewState.Success(entries)
            }.onFailure { e ->
                _viewState.value = LeaderboardViewState.Error(e.message ?: "Unknown error")
            }
        }
    }
}
