package com.bookreads.ui.leaderboard

import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.Button
import androidx.compose.material3.Tab
import androidx.compose.material3.TabRow
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import org.koin.compose.viewmodel.koinViewModel

@Composable
fun LeaderboardScreen(onNavigateBack: () -> Unit) {
    val viewModel = koinViewModel<LeaderboardViewModel>()
    val viewState by viewModel.viewState.collectAsState()
    val selectedWindow by viewModel.selectedWindow.collectAsState()

    LeaderboardScreenContent(
        viewState = viewState,
        selectedWindow = selectedWindow,
        onEvent = viewModel::handleEvent,
        onNavigateBack = onNavigateBack,
    )
}

@Composable
private fun LeaderboardScreenContent(
    viewState: LeaderboardViewState,
    selectedWindow: String,
    onEvent: (LeaderboardViewEvent) -> Unit,
    onNavigateBack: () -> Unit,
) {
    val windows = listOf("daily", "weekly", "monthly", "alltime")
    val labels = listOf("Daily", "Weekly", "Monthly", "All-time")

    Column(modifier = Modifier.fillMaxSize()) {
        TabRow(selectedTabIndex = windows.indexOf(selectedWindow).coerceAtLeast(0)) {
            windows.zip(labels).forEach { (window, label) ->
                Tab(
                    selected = selectedWindow == window,
                    onClick = { onEvent(LeaderboardViewEvent.SelectWindow(window)) },
                    text = { Text(label) },
                )
            }
        }

        when (viewState) {
            LeaderboardViewState.Loading -> Text(
                text = "Loading...",
                modifier = Modifier.padding(16.dp),
            )
            is LeaderboardViewState.Error -> Text(
                text = viewState.message,
                modifier = Modifier.padding(16.dp),
            )
            is LeaderboardViewState.Success -> {
                LazyColumn(modifier = Modifier.weight(1f)) {
                    items(viewState.entries) { entry ->
                        val hours = entry.totalSec / 3600
                        val minutes = (entry.totalSec % 3600) / 60
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp),
                        ) {
                            Text(text = "#${entry.rank} · ${entry.username} · ${hours}h ${minutes}m")
                        }
                    }
                }
            }
        }

        Button(
            onClick = onNavigateBack,
            modifier = Modifier.fillMaxWidth().padding(16.dp),
        ) {
            Text("Back")
        }
    }
}
