package com.bookreads.navigation

import androidx.navigation3.runtime.NavBackStack
import androidx.navigation3.ui.NavDisplay
import androidx.navigation3.ui.rememberNavBackStack
import com.bookreads.ui.home.HomeScreen
import com.bookreads.ui.leaderboard.LeaderboardScreen
import com.bookreads.ui.session.SessionScreen
import androidx.compose.runtime.Composable
import androidx.navigation3.runtime.entryProvider
import androidx.navigation3.runtime.entry

@Composable
fun NavApp() {
    val backStack: NavBackStack<AppRoutes> = rememberNavBackStack(AppRoutes.Home)

    NavDisplay(
        backStack = backStack,
        entryProvider = entryProvider {
            entry<AppRoutes.Home> {
                HomeScreen(
                    onNavigateToSession = { username ->
                        backStack.add(AppRoutes.Session(username = username))
                    },
                    onNavigateToLeaderboard = {
                        backStack.add(AppRoutes.Leaderboard)
                    },
                )
            }
            entry<AppRoutes.Session> { key ->
                SessionScreen(
                    username = key.username,
                    onNavigateToLeaderboard = {
                        backStack.add(AppRoutes.Leaderboard)
                    },
                    onNavigateBack = {
                        backStack.removeLastOrNull()
                    },
                )
            }
            entry<AppRoutes.Leaderboard> {
                LeaderboardScreen(
                    onNavigateBack = {
                        backStack.removeLastOrNull()
                    },
                )
            }
        },
    )
}
